+/// `opdbus/state/<plugin>` (snapshot + generation) and
+/// `opdbus/state/<plugin>/events` (per-commit receipts). Hints, not proof:
+/// receipts and the sealed blobs stay authoritative.
+pub const STATE_TOPIC_PREFIX: &str = "opdbus/state/";
